"use client";
import { useState, useEffect } from 'react';
import axios from 'axios';
import Link from 'next/link';
import { IconButton } from '@mui/material';
import { Edit as EditIcon, Delete as DeleteIcon } from '@mui/icons-material';
import Sidebar from '../components/sidebar'; 
import Navbar from '../components/Navbar';

export default function GestionGroupes() {
  const [etudiants, setEtudiants] = useState([]);
  const [selectedEtudiants, setSelectedEtudiants] = useState([]);
  const [groupes, setGroupes] = useState([]);
  const [showGroupes, setShowGroupes] = useState(false);
  const [groupeType, setGroupeType] = useState('alphabet');
  const [showGenerateForm, setShowGenerateForm] = useState(false);

  useEffect(() => {
    fetchData();
  }, []);
  const fetchData = async () => {
    try {
      const [etudiantsResponse, groupesResponse] = await Promise.all([
        axios.get('http://localhost:5000/api/etudiants'),
        axios.get('http://localhost:5000/api/groupes')
      ]);
  
      // Création d'une map pour retrouver les groupes par leur id
      const groupesMap = new Map(groupesResponse.data.map(g => [g.idGroupe, g.nomGroupe]));
  
      // Ajout du nom du groupe à chaque étudiant
      const etudiantsAvecGroupes = etudiantsResponse.data.map(etudiant => ({
        ...etudiant,
        nomGroupe: groupesMap.get(etudiant.idGroupe) || "-" // Affiche "-" si l'étudiant n'a pas de groupe
      }));
  
      setEtudiants(etudiantsAvecGroupes);
      setGroupes(groupesResponse.data);
    } catch (err) {
      console.error("Erreur lors de la récupération des données :", err);
    }
  };
  

  const toggleSelection = (id) => {
    setSelectedEtudiants((prevSelected) =>
      prevSelected.includes(id)
        ? prevSelected.filter((etudiantId) => etudiantId !== id)
        : [...prevSelected, id]
    );
  };

  const genererGroupe = async () => {
    if (selectedEtudiants.length === 0) {
      alert("Veuillez sélectionner des étudiants.");
      return;
    }
    try {
      await axios.post('http://localhost:5000/api/ajouterGroupe', { 
        etudiants: selectedEtudiants,
        groupeType: groupeType
      });
      alert("Groupe créé avec succès");
      setSelectedEtudiants([]);
      setShowGenerateForm(false);
      fetchData();
    } catch (err) {
      console.error("Erreur lors de la création du groupe :", err);
      alert("Erreur lors de la création du groupe");
    }
  };

  const deleteGroupe = async (idGroupe) => {
    if (!window.confirm("Voulez-vous vraiment supprimer ce groupe et ses étudiants ?")) return;
    try {
      await axios.delete(`http://localhost:5000/api/supprimerGroupe/${idGroupe}`);
      alert("Groupe supprimé avec succès");
      fetchData();
    } catch (err) {
      console.error("Erreur lors de la suppression du groupe :", err);
      alert("Erreur lors de la suppression du groupe");
    }
  };

  return (
    <div className="flex h-screen bg-gray-100">
      {/* Sidebar */}
      <Sidebar className="hidden lg:block bg-blue-700 text-white p-4 w-64 shadow-lg" />

      {/* Main content */}
      <div className="flex flex-col w-full bg-gray-50">
        {/* Navbar */}
        <Navbar className="bg-blue-600 text-white p-4 shadow-md" />

        <div className="container mx-auto p-6">
  <div className="mb-6 space-x-4">
    
    {/* Group Generation Button */}
    {!showGenerateForm ? (
      <button 
        onClick={() => setShowGenerateForm(true)} 
        className="bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-500 transition duration-300"
      >
        Générer Groupe
      </button>
    ) : (
      <div className="mb-4 space-y-2">
        <select
          value={groupeType}
          onChange={(e) => setGroupeType(e.target.value)}
          className="border p-2 rounded-md focus:outline-none shadow-sm"
        >
          <option value="alphabet">Groupe alphabétique</option>
          <option value="numerique">Groupe numérique</option>
        </select>
        <button 
          onClick={genererGroupe} 
          className="bg-blue-500 text-white px-4 py-2 rounded-lg hover:bg-blue-600"
        >
          Confirmer la création
        </button>
        <button 
          onClick={() => setShowGenerateForm(false)} 
          className="bg-red-500 text-white px-4 py-2 rounded-lg hover:bg-red-600 ml-2"
        >
          Annuler
        </button>
      </div>
    )}
    <button 
      onClick={() => setShowGroupes(!showGroupes)} 
      className="bg-blue-500 text-white px-6 py-3 rounded-lg hover:bg-blue-600"
    >
      {showGroupes ? 'Voir les Étudiants' : 'Voir les Groupes'}
    </button>
  </div>

  {/* Title of Groups or Students List */}
  <h2 className="text-2xl font-bold mb-4 text-blue-600">Liste des Groupes</h2>

  {/* Group List */}
  {showGroupes ? (
    <div className="mt-6">
      {groupes.map((groupe) => (
        <div key={groupe.idGroupe} className="bg-white p-4 mb-4 shadow-lg rounded-md">
          <h3 className="text-xl font-semibold text-blue-600">{groupe.nomGroupe}</h3>
          <p>{groupe.etudiants || "Aucun étudiant dans ce groupe"}</p>
        </div>
      ))}
    </div>
  ) : (
    // Student table
    <table className="min-w-full bg-white border border-gray-300 shadow-md rounded-lg">
      <thead className="bg-blue-500">
        <tr>
          <th className="border px-4 py-2 text-left text-white">Étudiants</th>
          <th className="border px-4 py-2 text-left text-white">Groupe</th>
          <th className="border px-4 py-2 text-left text-white">Actions</th>
        </tr>
      </thead>
      <tbody>
        {etudiants.map((etudiant) => (
          <tr key={etudiant.idEtudiant} className="hover:bg-gray-50">
            <td className="border px-4 py-2">
              <input 
                type="checkbox" 
                checked={selectedEtudiants.includes(etudiant.idEtudiant)} 
                onChange={() => toggleSelection(etudiant.idEtudiant)}
                disabled={etudiant.idGroupe}
              />
              {` ${etudiant.nom} ${etudiant.prenom}`}
            </td>
            <td className="border px-4 py-2">{etudiant.nomGroupe || "-"}</td>
            
            <td className="border px-4 py-2">
              {etudiant.idGroupe && (
                <>
                  <Link href={`/users/editgene/${etudiant.idEtudiant}`} passHref>
                    <IconButton color="primary">
                      <EditIcon />
                    </IconButton>
                  </Link>
                  <IconButton color="error" onClick={() => deleteGroupe(etudiant.idGroupe)}>
                    <DeleteIcon />
                  </IconButton>
                </>
              )}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  )}
</div>
 </div>
 </div>
  );
}
